import nextConfig from '@vunvault/config/eslint.next.mjs';

/**
 * The shared React/Next flat config, plus ignores for generated files.
 *
 * `next-env.d.ts` is generated by `next dev` and `next build` (and is gitignored):
 * it holds a triple-slash reference to Next's own route types, which
 * `@typescript-eslint/triple-slash-reference` rejects. Linting a generated file is
 * linting somebody else's output, so it is ignored here rather than suppressed rule
 * by rule. `.next/**` is ignored for the same reason — it is build output.
 *
 * `public/mockServiceWorker.js` is generated by `msw init` (the operator pre-step
 * after Task 42) and says "Please do NOT modify this file" — including its own
 * `eslint-disable` header, which ESLint 9 reports as an unused directive. Same
 * rule: generated vendor output is not ours to lint.
 */
export default [
  { ignores: ['next-env.d.ts', '.next/**', 'public/mockServiceWorker.js'] },
  ...nextConfig,
];
